// Renders the committed baseline metrics report (docs/research/typography-m0-baseline/README.md)
// from the canonical metrics object. Generated; do not edit the Markdown by hand.

const percent = (value) => `${(value * 100).toFixed(1)} %`;
const fixed = (value, digits = 3) => (value === null ? "n/a" : value.toFixed(digits));

export function renderBaselineMarkdown(report) {
  const lines = [];
  const push = (...values) => lines.push(...values);
  push(
    "# Typography baseline metrics (M0)",
    "",
    "<!-- Generated by `npm run typography-harness:update --workspace @glyphkiln/core`. Do not edit. -->",
    "",
    "Baseline of the **current** engine, before any typography milestone changes",
    "pixels. Defects are recorded on purpose: M0 measures them, later milestones",
    `fix them. Metric definitions: \`${report.metricsVersion}\``,
    "(`packages/glyphkiln-core/src/typography/quality-metrics.ts`). Shaper:",
    `\`${report.shaper}\`. Corpora: \`packages/glyphkiln-core/tests/typography/corpora/\`.`,
    `Snapshot digest: \`${report.snapshotSha256}\`.`,
    "",
    "Machine-readable values: [`metrics.json`](metrics.json). HarfBuzz spike:",
    "[`harfbuzz-spike.json`](harfbuzz-spike.json) and",
    "[ADR 0019](../../adr/0019-harfbuzz-shaper-qualification.md).",
    "",
    "## Corpora",
    "",
    "| Corpus | Entries |",
    "| --- | ---: |",
    ...Object.entries(report.corpora).map(([id, count]) => `| ${id} | ${count} |`),
    "",
    "## Shaping",
    "",
    `- C-MIX lines that fontkit shapes as one \`latn\` run: **${report.shaping.mixedLinesShapedAsLatin} of ${report.shaping.mixedLines}**`,
    "  (one script per line, plan §3.1).",
    `- Lines whose fontkit clusters could not be mapped exactly to the text: ${
      Object.values(report.shaping.clusterMappingInexact).flat().length
    }.`,
    "",
    "## Paragraphs (C-PARA, 32 px, ragged right)",
    "",
    "Adjustment ratio r uses TeX glue (stretch ½ space, shrink ⅓ space) over",
    "non-final lines; ragged setting does not apply it, so r says how far lines are",
    "from flush in units of available glue. Rag deviation is the standard deviation",
    "of non-final line widths over the measure.",
    "",
    "| Script | Width px | Lines | Mean abs r | Runts | Hyphenated lines | Rag deviation (mean) | Mean slack | Overfull |",
    "| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
  );
  for (const [script, widths] of Object.entries(report.paragraphs)) {
    for (const [width, row] of Object.entries(widths)) {
      push(
        `| ${script} | ${width} | ${row.lines} | ${fixed(row.meanAbsoluteAdjustmentRatio.mean, 2)} | ${row.runts} / ${row.paragraphs} | ${row.hyphenatedLines} | ${fixed(row.ragDeviation.mean)} | ${fixed(row.meanSlack.mean)} | ${row.overfullLines} |`,
      );
    }
  }
  push(
    "",
    "Thai breaks in C-PARA (orthographic check: inside a grapheme cluster, after a",
    "leading vowel, before a dependent vowel or mark; line edge: a line starting with",
    "ๆ or ฯ):",
    "",
    "| Width px | Inside cluster | Orthographic | Line edge |",
    "| ---: | ---: | ---: | ---: |",
    ...Object.entries(report.paragraphs.thai).map(
      ([width, row]) =>
        `| ${width} | ${row.thaiBreaks.insideGraphemeCluster} | ${row.thaiBreaks.orthographic} | ${row.thaiBreaks.lineEdge} |`,
    ),
    "",
    "## Mark offset invariance under tracking (C-TH, T08)",
    "",
    "Professional behaviour: no mark moves relative to its base, and line width grows",
    "by (clusters − 1) × tracking.",
    "",
    "| Tracking em | Marks moved | Max mark shift em | Max width excess em |",
    "| ---: | ---: | ---: | ---: |",
    ...report.markOffsetInvariance.map(
      (row) =>
        `| ${row.trackingEm} | ${row.marksMoved} / ${row.marks} | ${row.maximumMarkShiftEm} | ${row.maximumWidthExcessEm} |`,
    ),
    "",
    "## Cross-script x-height (T06)",
    "",
    "Ink top of Latin `x` over ink top of Thai `น` (exact curve extrema).",
    "",
    "| Pairing | Ratio | Delta |",
    "| --- | ---: | ---: |",
    ...Object.entries(report.crossScriptXHeight).map(
      ([name, value]) => `| ${name} | ${value.ratio} | ${value.delta} |`,
    ),
    "",
    "## Paint-only emphasis drift (C-EMPH, T07)",
    "",
    "Largest glyph x shift between a paint-only styled layout and the unstyled one",
    "(professional: 0).",
    "",
    "| Entry | Max shift px |",
    "| --- | ---: |",
    ...report.emphasisPaintOnlyDrift.map(
      (row) => `| ${row.id} | ${row.maximumShiftPx} |`,
    ),
    "",
    "## Break controls and edges (C-EDGE)",
    "",
    "| Entry | Lines | Broke at NBSP/NNBSP/WJ |",
    "| --- | --- | --- |",
    ...report.edges.map(
      (row) =>
        `| ${row.id} | ${row.lines.map((line) => `\`${visible(line)}\``).join(" / ")} | ${row.brokeAtNoBreakControl ? "yes" : "no"} |`,
    ),
    "",
    "## Probe regressions (C-PROBE, plan §3.1 and Static Ads T04)",
    "",
  );
  for (const probe of report.probes) {
    const facts = [];
    if (probe.script !== undefined) facts.push(`script \`${probe.script}\``);
    if (probe.glyphNames !== undefined) facts.push(`glyphs \`${probe.glyphNames}\``);
    if (probe.lines !== undefined) {
      facts.push(
        `lines ${probe.lines.map((line) => `\`${visible(line)}\``).join(" / ")}`,
      );
      if (probe.lineStartsWithMaiYamokOrPaiyannoi) facts.push("a line starts with ๆ/ฯ");
      if (probe.amountSplitFromUnit) facts.push("amount split from its unit");
    }
    if (probe.markDeviation !== undefined) {
      facts.push(
        `at ${probe.markDeviation.trackingEm} em tracking ${probe.markDeviation.marksMoved}/${probe.markDeviation.marks} marks move up to ${probe.markDeviation.maximumMarkShiftEm} em`,
      );
    }
    if (probe.boundaries !== undefined) {
      facts.push(
        `segment boundaries ${JSON.stringify(probe.boundaries)}, outside gold ${JSON.stringify(probe.boundariesOutsideGold)}`,
      );
    }
    push(`- **${probe.id}** (${probe.defect}): ${facts.join("; ")}.`);
  }
  const lbt = report.lineBreakTest;
  push(
    "",
    "## Unicode line breaking (T09 oracle)",
    "",
    `Current break opportunities against \`${lbt.source}\` (SHA-256 \`${lbt.sha256}\`):`,
    `**${lbt.passing} of ${lbt.cases}** cases (${percent(lbt.passRate)}) match exactly; break recall`,
    `${percent(lbt.breakRecall)}, precision ${percent(lbt.breakPrecision)}. T09 requires 100 %.`,
    "",
  );
  return `${lines.join("\n")}\n`;
}

function visible(text) {
  return text
    .replaceAll(" ", "⍽")
    .replaceAll(" ", "⍽")
    .replaceAll("​", "‸")
    .replaceAll("⁠", "⁀")
    .replaceAll("­", "¬")
    .replaceAll("|", "\\|");
}
